orders.sync:
function (doc, oldDoc, meta) {
  // Offline-first orders and customer actions. A customer's phone may CREATE one, as itself,
  // as 'pending'. Only the backend (admin / import) may advance its status.
  if (doc._deleted) { requireAdmin(); if (oldDoc) { channel("customer:" + oldDoc.customer_id); } return; }
  if (!doc.customer_id) { throw({forbidden: "customer_id is required"}); }
  if (oldDoc == null || oldDoc._deleted) {
    requireUser(doc.customer_id);
    if (doc.type !== "request") { throw({forbidden: "type must be 'request'"}); }
    if (doc.status !== "pending") { throw({forbidden: "new orders must be 'pending'"}); }
    if (doc._id.indexOf("order::" + doc.customer_id + "::") !== 0) { throw({forbidden: "id must be order::<customer_id>::<uuid>"}); }
  } else {
    if (oldDoc.customer_id !== doc.customer_id) { throw({forbidden: "customer_id is immutable"}); }
    requireAdmin();
  }
  channel("customer:" + doc.customer_id);
}
